#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""agent_slow.py -- 慢路径：让设备端 Agent 理解规则解析器搞不定的句子

【为什么需要它】
  规则解析器（nlp_parse.py）只认固定说法。实测遇到这些就整句丢弃：
    "今天天气不错，我想测试一下麦克风。"   -> intent=None -> 不下发
  长尾表达（"把刚才那个实验改成圆形再跑一次"、"哪台车跑偏了"）靠规则写不完，
  这时才动用设备端 Agent（LLM）。

【核心安全设计 —— 这是本模块最重要的部分】
  1. **白名单**：Agent 只能输出已登记的意图名，且参数经过类型/范围校验。
     任何不在表里的东西一律拒绝，绝不执行自由文本。
  2. **绝不执行 shell**：Agent 的输出只被解析成结构化命令，再由调用方决定怎么做。
     本模块连 subprocess 都不 import。
  3. **安全命令不可被 Agent 触发**：急停类（stop）在配置里被标记为
     safety_critical，Agent 路径不允许产生它 —— 急停必须走规则/物理按钮。
     理由：LLM 有延迟（秒级）且可能被误触发，不能让它当安全链路。
  4. **降级优先**：默认后端是 `offline`（正则兜底），不需要网络、不需要 LLM。
     配置好 agent 命令后才会真正调 LLM；LLM 不可用时自动降级，不影响主流程。

【后端】
  offline  : 纯规则兜底（默认，零依赖、零延迟、可测试）
  command  : 调用外部命令（例如设备上的 codex CLI），把提示词通过 stdin 传进去
             （预留接口；当前环境下未配置，配置后即可用）

用法：
  python3 agent_slow.py "今天天气不错，我想测试一下麦克风"
  python3 agent_slow.py --json "帮我看看哪台车跑偏了"
  python3 agent_slow.py --selftest
"""
# 【09-19 多车补丁】 编队/一起 这类「没提车号但就是多车」的说法要带 targets
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from nlp_parse import INTENTS, check_safety, parse as rule_parse  # noqa: E402

# ------------------------------------------------------------------ 白名单
# 允许 Agent 输出的意图（其余一律拒绝）。安全关键命令被明确排除。
AGENT_ALLOWED_INTENTS = {
    "start_formation": {"formation", "spacing_m", "duration_s", "robots"},
    "stop": set(),
    "reset": set(),
    "status": set(),
    # 检查四台车在不在线（只读，不动车）。用户会问"能连上四辆小车吗"。
    "car_check": set(),
    # 查询小车电池电量（只读：只订阅 /ros_robot_controller/battery）
    "battery": set(),
    # 每个动作都可以带 targets：要控制哪几台车（车号数组）。
    # 不写就是默认那台（板子上 CAR_IP 指定的）。
    "forward": {"distance_m", "targets"},
    "backward": {"distance_m", "targets"},
    "strafe_left": {"distance_m", "targets"},
    "strafe_right": {"distance_m", "targets"},
    "turn_left": {"angle_deg", "targets"},
    "turn_right": {"angle_deg", "targets"},
    "confirm": set(),
}

# 不允许由 Agent 触发的意图（安全关键，必须走规则匹配或物理按钮）
AGENT_FORBIDDEN_INTENTS = {"stop"}

ALLOWED_FORMATIONS = {"square", "line", "circle", "triangle", "column"}

PARAM_RANGES = {
    "spacing_m": (0.1, 10.0),
    "duration_s": (1.0, 3600.0),
    "distance_m": (-10.0, 10.0),
    "angle_deg": (-360.0, 360.0),
}


class AgentError(Exception):
    pass


# ------------------------------------------------------------------ 离线兜底
# 保守的同义词表：只做"规则解析器漏掉的常见说法"，不猜。
OFFLINE_SYNONYMS = [
    # (正则, 意图, 参数提取函数名)
    (r"(?:安静|别说话|闭嘴|静音)", "stop", None),
    (r"(?:有没有|是否)?(?:在)?(?:正常|运行|工作)(?:吗|么|没有)?[?？]?$", "status", None),
    (r"(?:现在)?(?:几台|多少)(?:车|机器人)", "status", None),
    (r"(?:再来|重来|重新|再)(?:跑|做|来)(?:一次|一遍)", "start_formation", None),
    (r"(?:开始|启动)(?:吧|一下)?$", "start_formation", None),
    (r"(?:回到|返回)(?:原点|初始)", "reset", None),
    # 车况问句的兜底（云端不通时也能接住"能连上小车吗"）
    (r"连(?:得|的)?上.{0,6}(?:小车|车辆|车)", "car_check", None),
    (r"(?:小车|车辆|车).{0,4}连(?:得|的)?上", "car_check", None),
    (r"(?:小车|车辆|车).{0,4}(?:在|连|通)(?:线|上)", "car_check", None),
    (r"(?:小车|车辆|车).{0,4}(?:都)?在(?:不在|吗)", "car_check", None),
]


def offline_understand(text):
    """纯规则兜底。命中返回与 parse() 同构的 dict，否则 intent=None。"""
    if not text:
        return {"text": text, "intent": None, "params": {}, "matched": [],
                "confidence": 0.0, "source": "offline"}
    t = text.strip()
    for pattern, intent, _ in OFFLINE_SYNONYMS:
        if re.search(pattern, t):
            return {"text": text, "intent": intent, "params": {}, "matched": [pattern],
                    "confidence": 0.5, "source": "offline"}
    return {"text": text, "intent": None, "params": {}, "matched": [],
            "confidence": 0.0, "source": "offline"}


# ------------------------------------------------------------------ 提示词
SYSTEM_PROMPT = """你是机器人实验平台的指令解析器。把用户的话转成严格的 JSON。

只允许输出下面这些意图（intent）之一：
- start_formation : 启动编队实验。参数 formation(正方形square/直线line/圆形circle/三角形triangle/纵队column)、spacing_m(米,数字)、duration_s(秒,数字)、robots(车号数组)
- reset           : 回到初始位置
- status          : 查询状态
- car_check       : 检查四辆小车在不在线（用户问"能连上小车吗""四台车都在线吗"
                    "车连上了吗"这类**关于连通性的问句**时用它。它只做检查，不移动车）
- battery         : 查询小车**电池电量**（用户问"电量怎么样""电池还有多少电"
                    "剩余电量"这类问题时用它。只读，不移动车）
- forward         : 前进。参数 distance_m(米,数字)
- backward        : 后退。参数 distance_m(米,数字)
- strafe_left     : 向左**平移**（麦克纳姆轮横移，车头方向不变）。参数 distance_m(米,数字)
- strafe_right    : 向右**平移**（同上）。参数 distance_m(米,数字)
- turn_left       : 左转。参数 angle_deg(度,数字)
- turn_right      : 右转。参数 angle_deg(度,数字)
- confirm         : 用户表示确认
- none            : 无法判断，或与机器人控制无关

规则：
1. 只输出 JSON，不要解释、不要 markdown 代码块。
2. 单步请求格式：{"intent": "...", "params": {...}, "confidence": 0.0~1.0}
3. 无法判断时输出 {"intent": "none", "params": {}, "confidence": 0}
4. 多步请求（"先…再…然后…"）必须**一次给全**，用 steps 数组按顺序列出：
   {"steps":[{"intent":"forward","params":{"distance_m":1}},
             {"intent":"turn_left","params":{"angle_deg":90}}],"confidence":0.9}
   · 最多 6 步，严格按说话顺序排列
   · steps 里不要写 stop —— 每个动作结束都会自动停下
   · 不要拆成多次回答，也不要只回答第一步
5. 单独要求停止/急停的句子（例如只说"停下"）不在你的权限内，输出 none。
   这是安全要求：急停必须由本地规则或物理按钮处理，比你更快更可靠。
6. 目标车：用户指定了要控制哪几台车时，给动作加 targets 参数（车号数组）。
   "所有车/全部/四台车/大家一起" -> targets:[1,2,3,4]
   还有一类说法**没提车号但就是多车**：编队、一起、一块、协同、集体。
   例如「小车编队，后退0.5米」= 所有车一起后退 0.5 米：
       输出：{"intent":"backward","params":{"distance_m":0.5,"targets":[1,2,3,4]},"confidence":0.9}
   注意：「编队+动作」按**动作**理解（backward/forward/... 加 targets），
   start_formation 只用于用户明确要"排队形/做实验"（排成正方形、给间距、跑多久）时。
   "2号车" -> targets:[2]；"1号和3号" -> targets:[1,3]
   用户**没说**车号时不要加 targets（默认只控制配置好的那一台）。
7. 不要发明参数名，不要输出未知意图。

示例：
用户：让所有车往前走半米
输出：{"intent":"forward","params":{"distance_m":0.5,"targets":[1,2,3,4]},"confidence":0.95}

用户：2号车左转90度
输出：{"intent":"turn_left","params":{"angle_deg":90,"targets":[2]},"confidence":0.95}

用户：让四台小车排成正方形，间距0.8米，跑半分钟
输出：{"intent":"start_formation","params":{"formation":"square","spacing_m":0.8,"duration_s":30},"confidence":0.95}

用户：小车编队，后退0.5米 / 大家排好队一起后退半米 / 四台车编队往后退0.5米
输出：{"intent":"backward","params":{"distance_m":0.5,"targets":[1,2,3,4]},"confidence":0.9}

用户：先往前走一米，再左转90度，最后后退半米
输出：{"steps":[{"intent":"forward","params":{"distance_m":1}},{"intent":"turn_left","params":{"angle_deg":90}},{"intent":"backward","params":{"distance_m":0.5}}],"confidence":0.9}

用户：向左横移半米
输出：{"intent":"strafe_left","params":{"distance_m":0.5},"confidence":0.95}

用户：能连上四辆小车吗
输出：{"intent":"car_check","params":{},"confidence":0.95}

用户：四台车都在线吗 / 小车连上了吗 / 检查一下小车
输出：{"intent":"car_check","params":{},"confidence":0.95}

用户：小车的电量怎么样了 / 电池还有多少电 / 查一下剩余电量
输出：{"intent":"battery","params":{},"confidence":0.95}

用户：小车现在状态怎么样
输出：{"intent":"status","params":{},"confidence":0.9}

注意区分 car_check 和 status：
  car_check = 问"小车连得上吗/在不在线"（四台车通不通）；
  status    = 问"跑得怎么样/进度如何"（当前这一轮任务的状态）。

注意区分"转向"和"平移"：左转/右转 = 车头转动（turn_left/turn_right）；
向左/向右平移、横移、侧移 = 车头不动、整车横向移动（strafe_left/strafe_right）。

用户：停下
输出：{"intent":"none","params":{},"confidence":0}

用户：今天天气不错
输出：{"intent":"none","params":{},"confidence":0}
"""


def build_prompt(text):
    return SYSTEM_PROMPT + "\n用户：" + (text or "")


# ------------------------------------------------------------------ 解析 Agent 输出
def _extract_json(raw):
    """从 Agent 回复里抠出第一个 JSON 对象（容忍代码块/前后废话）。"""
    if not raw:
        raise AgentError("空回复")
    s = raw.strip()
    # 去掉 ```json ... ``` 包裹
    m = re.search(r"```(?:json)?\s*(.+?)\s*```", s, re.S)
    if m:
        s = m.group(1).strip()
    # 直接尝试
    try:
        return json.loads(s)
    except ValueError:
        pass
    # 退而求其次：找第一个平衡的大括号片段
    depth = 0
    start = None
    for i, ch in enumerate(s):
        if ch == "{":
            if depth == 0:
                start = i
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0 and start is not None:
                frag = s[start:i + 1]
                try:
                    return json.loads(frag)
                except ValueError:
                    start = None
    raise AgentError("回复里找不到合法 JSON：%r" % raw[:200])


def validate(parsed, allow_safety=False):
    """严格校验 Agent 输出。通过返回 (True, 规范化后的 dict)，否则 (False, 原因)。

    allow_safety=True 时放行安全关键意图（stop）。只在**多步计划**里用：
    计划里"做完这些再停下"属于普通编排动作，不是要抢时间的急停；
    单独的急停请求仍然只能由本地规则产出。
    """
    if not isinstance(parsed, dict):
        return False, "不是 JSON 对象"

    intent = parsed.get("intent")
    if not isinstance(intent, str):
        return False, "缺少 intent 字段"
    intent = intent.strip().lower()

    if intent in ("none", "null", ""):
        return False, "Agent 判定为无法识别"
    if intent in AGENT_FORBIDDEN_INTENTS and not allow_safety:
        return False, "意图 %s 属安全关键，不允许由 Agent 触发" % intent
    if intent not in AGENT_ALLOWED_INTENTS:
        return False, "意图 %s 不在白名单内" % intent

    raw_params = parsed.get("params") or {}
    if not isinstance(raw_params, dict):
        return False, "params 不是对象"

    allowed = AGENT_ALLOWED_INTENTS[intent]
    params = {}
    for k, v in raw_params.items():
        if k not in allowed:
            return False, "意图 %s 不接受参数 %s" % (intent, k)
        # 数值参数：转 float 并做范围检查
        if k in PARAM_RANGES:
            try:
                fv = float(v)
            except (TypeError, ValueError):
                return False, "参数 %s 不是数字：%r" % (k, v)
            lo, hi = PARAM_RANGES[k]
            if not (lo <= fv <= hi):
                return False, "参数 %s=%.3f 超出允许范围 [%s, %s]" % (k, fv, lo, hi)
            params[k] = fv
        elif k == "formation":
            if v not in ALLOWED_FORMATIONS:
                return False, "未知队形 %r（允许：%s）" % (v, ",".join(sorted(ALLOWED_FORMATIONS)))
            params[k] = v
        elif k in ("robots", "targets"):
            if not isinstance(v, (list, tuple)):
                return False, "%s 必须是数组" % k
            try:
                rs = [int(x) for x in v]
            except (TypeError, ValueError):
                return False, "%s 元素必须是整数" % k
            if not rs or any(r < 1 or r > 8 for r in rs):
                return False, "%s 取值须在 1~8 之间：%r" % (k, rs)
            params[k] = rs
        else:
            params[k] = v

    try:
        conf = float(parsed.get("confidence", 0) or 0)
    except (TypeError, ValueError):
        conf = 0.0
    conf = max(0.0, min(1.0, conf))

    return True, {"text": parsed.get("text", ""), "intent": intent, "params": params,
                  "matched": ["agent"], "confidence": conf, "source": "agent"}


MAX_PLAN_STEPS = 6


def extract_targets(text):
    """从文本里抠出目标车号（确定性规则，急停这类不过模型的句子也适用）。

    "所有车/全部/四台车" -> [1,2,3,4]
    "2号车"、"小车2"、"1号和3号" -> [2] / [1,3]
    没提车号 -> []（默认只控制配置好的那一台）
    """
    t = text or ""
    if re.search(r"所有车|全部车|四台车|每台车|大家一起", t):
        return [1, 2, 3, 4]
    nums = re.findall(r"([1-8])\s*号车", t)
    if not nums:
        nums = re.findall(r"小车\s*([1-8])", t)
    if not nums:
        nums = re.findall(r"([1-8])\s*号", t)
    return sorted({int(n) for n in nums})


def validate_plan(parsed):
    """校验多步计划（steps 数组）。返回 (True, [step, ...]) 或 (False, 原因)。

    每一步都过和单步完全相同的白名单 + 类型 + 范围校验，不另开一条宽松通道。
    """
    if not isinstance(parsed, dict):
        return False, "不是 JSON 对象"
    raw = parsed.get("steps")
    if not isinstance(raw, list) or not raw:
        return False, "steps 不是非空数组"
    if len(raw) > MAX_PLAN_STEPS:
        return False, "步骤过多（%d 步，上限 %d）" % (len(raw), MAX_PLAN_STEPS)
    steps = []
    for i, item in enumerate(raw, 1):
        ok, res = validate(item, allow_safety=True)
        if not ok:
            return False, "第 %d 步不合法：%s" % (i, res)
        steps.append({"intent": res["intent"], "params": res["params"]})
    return True, steps


# ------------------------------------------------------------------ 后端
def run_command_backend(text, cmd, timeout=120):
    """调用外部命令当 LLM 后端：提示词从 stdin 进，JSON 从 stdout 出。

    当前环境没有配置这个（用户离开、且调用 LLM 需要网络与额度），
    所以默认不启用；配置后即可切换。
    """
    try:
        r = subprocess.run(cmd, input=build_prompt(text), capture_output=True,
                           text=True, timeout=timeout)
    except Exception as exc:  # noqa: BLE001
        raise AgentError("后端命令执行失败：%s" % exc)
    if r.returncode != 0:
        raise AgentError("后端命令返回码 %d：%s" % (r.returncode, (r.stderr or "")[:200]))
    return _extract_json(r.stdout)


def understand(text, backend="offline", cmd=None, timeout=120, verbose=False,
               rules_first=True, allow_plan=False):
    """慢路径主入口。

    返回结构化理解结果：
      {"intent":..., "params":..., "source": "rule"|"offline"|"agent", "ok": bool, "reason": str}

    保守原则：任何一步失败都不抛异常给调用方，而是返回 ok=False + reason，
    由调用方决定是"不下发"还是"提示用户"。
                ensure_ascii=False) + "\n")
    except OSError:
        pass
    return txt


def _intent_to_text(sl):
    """把慢路径得到的结构化意图，转成规则解析器认得的说法。

    为什么绕这一圈：不想为慢路径再开一条下发通道（会绕过同一套模板与安全校验）。
    而是把它"翻译"回自然语言，仍交给 vcmd 统一执行 —— 单一出口，少一处出错点。
    """
    intent = sl.get("intent") or ""
    p = sl.get("params") or {}
    form_cn = {"square": "正方形", "line": "直线", "circle": "圆形",
               "triangle": "三角形", "column": "纵队"}.get(p.get("formation"), "")
    if intent == "start_formation":
        s = "做一个%s编队" % form_cn
        if p.get("spacing_m") is not None:
            s += "，间距%s米" % p["spacing_m"]
        if p.get("duration_s") is not None:
            s += "，运行%s秒" % p["duration_s"]
        if p.get("robots"):
            s += "，%d台车" % len(p["robots"])
        return s
    if intent == "forward":
        return "前进%s米" % p.get("distance_m", 1)
    if intent == "backward":
        return "后退%s米" % p.get("distance_m", 1)
    if intent == "turn_left":
        return "左转%s度" % p.get("angle_deg", 90)
    if intent == "turn_right":
        return "右转%s度" % p.get("angle_deg", 90)
    if intent == "strafe_left":
        return "向左横移%s米" % p.get("distance_m", 1)
    if intent == "strafe_right":
        return "向右横移%s米" % p.get("distance_m", 1)
    if intent == "reset":
        return "回到初始位置"
    if intent == "status":
        return "现在状态怎么样"
    if intent == "confirm":
        return "确认"
    # stop 等安全关键意图不会从这里来（agent_slow 已禁止）
    return sl.get("text") or ""


# 车号的中文写法 -> ASCII（ASR 输出的是"小车一""一号车"这种）
_CAR_DIGIT = {"1": "1", "2": "2", "3": "3", "4": "4",
              "一": "1", "二": "2", "两": "2", "三": "3", "四": "4"}


def _extract_robots(text):
    """从识别文本里抽出目标车号，返回 "1,2,3,4" 这样的字符串（抽不到返回 ""）。

    """start_formation 的参数抽取：队形 / 间距 / 时长 / 目标车。"""
    for form, words in FORMATION_WORDS.items():
        for w in words:
            if w in text:
                result["params"]["formation"] = form
                result["matched"].append(w)
                break
        if "formation" in result["params"]:
            break

    # 间距：间距/间隔/距离/相隔 [+是/为/约] + 数字 + [单位]
    m = re.search(r"(?:间距|间隔|距离|相隔|边长|半径)\s*(?:是|为|大约|约|设置成|设为)?\s*"
                  + NUM + r"\s*" + DIST_UNIT + r"?", text)
    if m:
        val = dist_number(m.group(1), m.group(2))
        if val is not None:
            result["params"]["spacing_m"] = val
            result["matched"].append(m.group(0).strip())

    # 时长：**必须带时间单位**，否则"跑一个圆形队形"会把"一"当成 1 秒（实测踩过）
    m = re.search(r"(?:运行|持续|跑|执行|进行|计时|时长|共|一共)?\s*"
                  + NUM + r"\s*(秒|分钟|min|s\b)", text)
    if m:
        val = cn_number(m.group(1))
        if val is not None:
            if m.group(2) in ("分钟", "min"):
                val *= 60
            result["params"]["duration_s"] = val
            result["matched"].append(m.group(0).strip())
    else:
        # 兜住"运行三十"这种省略单位的说法（只在有明确动词时）
        m2 = re.search(r"(?:运行|持续|计时|时长)\s*" + NUM, text)
        if m2:
            val = cn_number(m2.group(1))
            if val is not None:
                result["params"]["duration_s"] = val
                result["matched"].append(m2.group(0).strip())

    if re.search(r"(?:四|4)\s*(?:台|辆|个)", text):
        result["params"]["robots"] = [1, 2, 3, 4]
    elif re.search(r"(?:全部|所有|全体|都)", text):
        result["params"]["robots"] = [1, 2, 3, 4]

    formation_motion = bool(
        re.search(r"(?:保持|维持).{0,6}(?:方阵|队形|编队)", text)
        or re.search(r"(?:方阵|队形|编队).{0,20}(?:左转|右转|转向|转弯)", text)
    )
    if formation_motion:
        result["params"]["mission"] = "square-turn"
        distance = re.search(
            r"(?:前进|向前|往前走|往前开)\s*" + NUM + r"\s*" + DIST_UNIT,
            text,
        )
        if distance:
            result["params"]["straight_m"] = dist_number(distance.group(1), distance.group(2))
            result["matched"].append(distance.group(0))
        if "左转" in text or "向左转" in text:
            result["params"]["turn_direction"] = "left"
        elif "右转" in text or "向右转" in text:
            result["params"]["turn_direction"] = "right"
        angle = re.search(NUM + r"\s*(?:度|°)", text)
        if angle:
            result["params"]["turn_angle_deg"] = cn_number(angle.group(1))
            result["matched"].append(angle.group(0))


# ------------------------------------------------------------------ 默认值 / 安全
def normalized_defaults(defaults):
    """把 defaults 规范化成 {intent: {param: value}}。

    支持两种写法，保证向后兼容：
      旧（扁平）：{"formation": "square", "spacing_m": 0.8, "distance_m": 0.5}
      新（分组）：{"start_formation": {...}, "forward": {...}, "turn_left": {...}}

    为什么要分组：`_defaults` 里同时有编队参数和运动参数时，扁平结构会把
    distance_m/angle_deg 也灌进 start_formation 指令里（实测踩过），
    而且 forward/turn/strafe 这些意图**根本拿不到默认值**。
    """
    if not defaults:
        return {}
    # 判断是不是"分组"结构：所有非下划线键的值都是 dict
    grouped = all(isinstance(v, dict) for k, v in defaults.items() if not k.startswith("_"))
    if defaults and grouped:
        return {k: dict(v) for k, v in defaults.items() if not k.startswith("_")}
    # 扁平结构 -> 只归给 start_formation（保持旧行为，但不再污染其它意图）
    return {"start_formation": dict(defaults)}


def apply_defaults(parsed, defaults):
    """按意图补全用户没说清楚的参数。

    只给当前意图补它自己的默认值——不同意图的参数互不串味。
    返回 parsed，并记录补了哪些键到 parsed["defaults_applied"]。
    """
    intent = parsed.get("intent")
    if not intent:
        return parsed
    table = normalized_defaults(defaults)
    # 兼容：扁平结构只归给 start_formation；若调用方直接传了整张表，
    # 且当前意图没有专属条目，则不补（宁缺勿滥）。
    per_intent = table.get(intent) or {}
    if not per_intent:
        return parsed
    p = parsed.setdefault("params", {})
    for key, val in per_intent.items():
        if key not in p:
            p[key] = val
            parsed.setdefault("defaults_applied", []).append(key)
    return parsed


def check_safety(parsed, limits=None):
    """返回违规项列表（空 = 通过）。这是"实验能不能安全运行"的最小实现。

    覆盖两类意图：
      * start_formation：间距、时长
      * forward/backward/strafe_*/turn_*：单步距离、转角

    注意：这里只查"参数是否越界"这类可以纯计算判断的东西。
    真实安全（急停、避障）必须在车端做，不能只靠这一层；
    ros_car.py 里还有一层硬上限，两层独立生效。
    """
    limits = dict(DEFAULT_LIMITS, **(limits or {}))
    problems = []
    intent = parsed.get("intent")
    if not intent:
        return problems
    p = parsed.get("params", {}) or {}

    if intent == "start_formation":
        spacing = p.get("spacing_m")
        if spacing is not None:
            if spacing < limits["spacing_min"]:
                problems.append("间距 %.2f m 小于最小安全间距 %.2f m" % (spacing, limits["spacing_min"]))
            if spacing > limits["spacing_max"]:
                problems.append("间距 %.2f m 超过场地可用范围 %.2f m" % (spacing, limits["spacing_max"]))
        duration = p.get("duration_s")
        if duration is not None:
            if duration <= 0:
                problems.append("时长必须为正数")
            elif duration > limits["duration_max"]:
                problems.append("时长 %.0f s 超过单次实验上限 %.0f s" % (duration, limits["duration_max"]))
        if p.get("formation") is None:
            problems.append("没听清队形（正方形/直线/圆形/三角形/纵队）")
        robots = p.get("robots")
        if robots is not None and not isinstance(robots, (list, tuple)):
            problems.append("目标车参数格式不对：%r" % (robots,))
        if p.get("mission") == "square-turn":
            if p.get("formation") != "square":
                problems.append("当前编队转向任务只支持方阵")
            if p.get("straight_m") is None:
                problems.append("没听清方阵要前进多少米")
            if p.get("turn_angle_deg") != 90.0:
                problems.append("当前编队转向任务只支持九十度转向")
        return problems

    if intent in ("forward", "backward", "strafe_left", "strafe_right"):
        d = p.get("distance_m")
        if d is None:
            problems.append("没听清要移动多少米")
        elif d <= 0:
            problems.append("移动距离必须为正数")
        elif abs(d) > limits["distance_max"]:
            problems.append("移动距离 %.2f m 超过单步上限 %.2f m" % (d, limits["distance_max"]))

    if intent in ("turn_left", "turn_right"):
        a = p.get("angle_deg")
        if a is None:
            problems.append("没听清要转多少度")
        elif a <= 0:
            problems.append("转角必须为正数")
        elif abs(a) > limits["angle_max"]:
            problems.append("转角 %.0f 度超过单步上限 %.0f 度" % (a, limits["angle_max"]))

    return problems
