class PulseAudioGate(object):
    """跑采集时让 PulseAudio 别抢设备，退出后恢复。"""

    def __init__(self, enabled=True):
        self.enabled = enabled
        self.was_active = False

    def __enter__(self):
        if not self.enabled or not shutil.which("systemctl"):
            return self
        rc = subprocess.call(["systemctl", "--user", "is-active", "--quiet", "pulseaudio.service"],
                             stderr=subprocess.DEVNULL)
        if rc == 0:
            subprocess.call(["systemctl", "--user", "stop", "pulseaudio.socket", "pulseaudio.service"],
                            stderr=subprocess.DEVNULL)
            time.sleep(0.8)
            self.was_active = True
            print("[1/4] 已让开 PulseAudio（退出后自动恢复）", file=sys.stderr)
        return self

    def __exit__(self, *exc):
        if self.was_active:
            subprocess.call(["systemctl", "--user", "start", "pulseaudio.socket", "pulseaudio.service"],
                            stderr=subprocess.DEVNULL)
            print("[1/4] 已恢复 PulseAudio", file=sys.stderr)
        return False


def capture_once(args) -> tuple:
    """按 VAD 录一句话，返回 (wav_path, 语音秒数) 或 (None, 0)。"""
    rate = args.rate
    ch = args.channels
    block = int(rate * 0.125) * 2 * ch          # 0.125 s
    block_sec = 0.125

    cmd = ["arecord", "-D", args.device, "-f", "S16_LE", "-r", str(rate),
           "-c", str(ch), "-t", "raw", "-q", "-"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0)

    skip_blocks = int(round(args.skip_start / block_sec))
    levels, floor_db = [], -70.0
    in_speech, speech_run, silence = False, 0, 0
    buf = bytearray()
    t0 = time.time()

    try:
        while True:
            data = proc.stdout.read(block)
            if not data:
                print("[1/4] 采集流中断（设备被占或驱动卡死？）", file=sys.stderr)
                return None, 0.0
            if time.time() - t0 > args.max_wait:
                print("[1/4] %.0f 秒内没听到说话，退出" % args.max_wait, file=sys.stderr)
                return None, 0.0
            if skip_blocks > 0:
                skip_blocks -= 1
                continue

            bias = audioop.avg(data, 2)
            ac = audioop.bias(data, 2, -bias) if bias else data
            rms = audioop.rms(ac, 2) or 1
            db = 20.0 * math.log10(rms / 32768.0)
            if len(levels) >= 40:
                floor_db = sorted(levels)[max(0, int(len(levels) * 0.2) - 1)]
            speech = db > floor_db + args.start_db

            if args.verbose:
                print("    电平 %6.1f 底噪 %6.1f 阈值 %6.1f %s"
                      % (db, floor_db, floor_db + args.start_db, "<-语音" if speech else ""), file=sys.stderr)

            if not in_speech:
                levels.append(db)
                del levels[:-80]
                if speech:
                    speech_run += 1
                    buf += data
                    if speech_run >= args.start_blocks:
                        in_speech = True
                        silence = 0
                        print("[1/4] 检测到语音，开始录音…", file=sys.stderr)
                else:
                    speech_run = 0
                    buf = bytearray()
            else:
                buf += data
                if speech:
                    silence = 0
                else:
                    silence += 1
                too_long = len(buf) / float(2 * ch * rate) > args.max_utterance
                if silence * block_sec >= args.end_silence or too_long:
                    dur = len(buf) / float(2 * ch * rate)
                    if dur < args.min_utterance:
                        print("[1/4] 太短（%.2f s），丢弃" % dur, file=sys.stderr)
                        return None, 0.0
                    # 采集是 16k/2ch 原始 PCM，直接写 wav，转码交给 ASR 前处理
                    path = args.save_wav or "/tmp/vcmd_utt.wav"
                    save_wav(path, buf, rate, ch)
                    print("[1/4] 录到 %.2f s 语音 → %s" % (dur, path), file=sys.stderr)
                    return path, dur
    finally:
        try:
            proc.terminate()
            proc.wait(timeout=2)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass


def save_wav(path: str, pcm: bytes, rate: int, channels: int) -> None:
    import wave
    with wave.open(path, "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(bytes(pcm))


def to_asr_wav(src: str, dst: str, rate: int = 16000) -> bool:
    """把采集到的多通道 wav 转成单声道 16k，减小上传体积（ffmpeg 在板上已有）。"""
    if not shutil.which("ffmpeg"):
        return False
    rc = subprocess.call(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                          "-i", src, "-ar", str(rate), "-ac", "1", dst])
    return rc == 0


